def match(orders):
    buys = []  # (price, arrival_time, id, remaining_qty)
    sells = []  # (price, arrival_time, id, remaining_qty)
    trades = []
    order_map = {}  # id -> (side, index in buys or sells)
    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, idx = order_map[order_id]
                if side == 'buy':
                    if idx < len(buys) and buys[idx][2] == order_id:
                        buys[idx] = None
                elif side == 'sell':
                    if idx < len(sells) and sells[idx][2] == order_id:
                        sells[idx] = None
                del order_map[order_id]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[-1]
            price = order[3] if len(order) > 4 else None

            arrival_time += 1

            if side == 'buy':
                remaining_qty = qty

                # Match against resting sells
                i = 0
                while i < len(sells) and remaining_qty > 0:
                    if sells[i] is None:
                        i += 1
                        continue

                    sell_price, sell_arrival, sell_id, sell_qty = sells[i]

                    # Check if match is possible
                    match_price = None
                    if order_type == 'market':
                        match_price = sell_price
                    elif order_type in ['limit', 'ioc']:
                        if price >= sell_price:
                            match_price = sell_price

                    if match_price is not None:
                        trade_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, match_price, trade_qty])

                        remaining_qty -= trade_qty
                        sells[i] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

                        if sell_qty - trade_qty == 0:
                            sells[i] = None
                            del order_map[sell_id]

                    i += 1

                # Add remaining qty to order book if limit order
                if remaining_qty > 0 and order_type == 'limit':
                    buys.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('buy', len(buys) - 1)
                    # Sort buys: highest price first, then earliest arrival
                    buys.sort(key=lambda x: (-x[0], x[1]))
                    # Update indices in order_map
                    for idx, buy in enumerate(buys):
                        if buy is not None:
                            order_map[buy[2]] = ('buy', idx)

            else:  # side == 'sell'
                remaining_qty = qty

                # Match against resting buys
                i = 0
                while i < len(buys) and remaining_qty > 0:
                    if buys[i] is None:
                        i += 1
                        continue

                    buy_price, buy_arrival, buy_id, buy_qty = buys[i]

                    # Check if match is possible
                    match_price = None
                    if order_type == 'market':
                        match_price = buy_price
                    elif order_type in ['limit', 'ioc']:
                        if price <= buy_price:
                            match_price = buy_price

                    if match_price is not None:
                        trade_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, match_price, trade_qty])

                        remaining_qty -= trade_qty
                        buys[i] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

                        if buy_qty - trade_qty == 0:
                            buys[i] = None
                            del order_map[buy_id]

                    i += 1

                # Add remaining qty to order book if limit order
                if remaining_qty > 0 and order_type == 'limit':
                    sells.append((price, arrival_time, order_id, remaining_qty))
                    order_map[order_id] = ('sell', len(sells) - 1)
                    # Sort sells: lowest price first, then earliest arrival
                    sells.sort(key=lambda x: (x[0], x[1]))
                    # Update indices in order_map
                    for idx, sell in enumerate(sells):
                        if sell is not None:
                            order_map[sell[2]] = ('sell', idx)

    return trades

